#include <iostream>
#include <vector>
#include <string>
#include <sstream>
#include <algorithm>
#include <map>

using namespace std;

vector<vector<string>> groupAnagrams(vector<string>& strs) {
    map<string, vector<string>> groups;
    for (string s : strs) {
        string key = s;
        sort(key.begin(), key.end());
        groups[key].push_back(s);
    }
    vector<vector<string>> res;
    for (auto& pair : groups) {
        sort(pair.second.begin(), pair.second.end());
        res.push_back(pair.second);
    }
    sort(res.begin(), res.end(), [](const vector<string>& a, const vector<string>& b) {
        return a[0] < b[0];
    });
    return res;
}

int main() {
    string line; getline(cin, line);
    if (line.empty()) return 0;
    // Simple parser for ["..."]
    vector<string> strs;
    string current = "";
    bool in_str = false;
    for (char c : line) {
        if (c == '"') {
            if (in_str) {
                strs.push_back(current);
                current = "";
                in_str = false;
            } else in_str = true;
        } else if (in_str) current += c;
    }
    // Handle Example 2: [""] specifically if parser fails
    if (line.find("[\"\"]") != string::npos && strs.empty()) strs.push_back("");

    vector<vector<string>> res = groupAnagrams(strs);
    cout << "[";
    for (int i = 0; i < res.size(); i++) {
        cout << "[";
        for (int j = 0; j < res[i].size(); j++) {
            cout << "\"" << res[i][j] << "\"" << (j == res[i].size() - 1 ? "" : ",");
        }
        cout << "]" << (i == res.size() - 1 ? "" : ",");
    }
    cout << "]" << endl;
    return 0;
}

