import java.util.*;
import java.io.*;

public class Main {
    public static List<List<String>> groupAnagrams(String[] strs) {
        Map<String, List<String>> map = new HashMap<>();
        for (String s : strs) {
            char[] ca = s.toCharArray();
            Arrays.sort(ca);
            String key = String.valueOf(ca);
            if (!map.containsKey(key)) map.put(key, new ArrayList<>());
            map.get(key).add(s);
        }
        List<List<String>> res = new ArrayList<>();
        for (List<String> list : map.values()) {
            Collections.sort(list);
            res.add(list);
        }
        res.sort(Comparator.comparing(a -> a.get(0)));
        return res;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine(); if (line == null) return;
        line = line.substring(1, line.length() - 1);
        if (line.isEmpty()) { System.out.println("[]"); return; }
        List<String> strs = new ArrayList<>();
        String[] parts = line.split(",");
        for (String p : parts) strs.add(p.trim().replace("\"", ""));
        List<List<String>> res = groupAnagrams(strs.toArray(new String[0]));
        System.out.println(res.toString().replace(" ", ""));
    }
}

