const fs = require('fs');

function groupAnagrams(strs) {
    let map = new Map();
    for (let s of strs) {
        let key = s.split('').sort().join('');
        if (!map.has(key)) map.set(key, []);
        map.get(key).push(s);
    }
    let res = Array.from(map.values()).map(v => v.sort());
    res.sort((a, b) => a[0].localeCompare(b[0]));
    return res;
}

